using System;
using NUnit.Framework;

/// <summary>
/// Golden calendar vectors shared by the Unity and .NET test hosts during CORE-A.
/// Values are explicit contract expectations, not generated by another calendar implementation.
/// </summary>
public sealed class CalendarParityTests
{
    private static readonly DateVector[] DateVectors =
    {
        new DateVector("one-day year day zero", 1, 1, 1, null, 0L, 0L, 1, 1, 1, 1, 1L, 1L, 1L, "1/1/1/uniform:1"),
        new DateVector("one-day year next year", 1, 1, 1, null, 1L, 1L, 1, 1, 1, 1, 1L, 1L, 1L, "1/1/1/uniform:1"),
        new DateVector("conventional final day", 12, 1, 30, null, 359L, 0L, 12, 1, 30, 30, 360L, 30L, 360L, "12/30/360/uniform:30"),
        new DateVector("conventional year boundary", 12, 1, 30, null, 360L, 1L, 1, 1, 1, 1, 1L, 30L, 360L, "12/30/360/uniform:30"),
        new DateVector("unequal first month end", 3, 1, 1, new[] { 10, 20, 5 }, 9L, 0L, 1, 10, 10, 1, 10L, 10L, 35L, "3/1/35/custom:10,20,5"),
        new DateVector("unequal second month start", 3, 1, 1, new[] { 10, 20, 5 }, 10L, 0L, 2, 1, 1, 1, 11L, 20L, 35L, "3/1/35/custom:10,20,5"),
        new DateVector("unequal third month start", 3, 1, 1, new[] { 10, 20, 5 }, 30L, 0L, 3, 1, 1, 1, 31L, 5L, 35L, "3/1/35/custom:10,20,5"),
        new DateVector("unequal final day", 3, 1, 1, new[] { 10, 20, 5 }, 34L, 0L, 3, 5, 5, 1, 35L, 5L, 35L, "3/1/35/custom:10,20,5"),
        new DateVector("unequal year boundary", 3, 1, 1, new[] { 10, 20, 5 }, 35L, 1L, 1, 1, 1, 1, 1L, 10L, 35L, "3/1/35/custom:10,20,5"),
        new DateVector("long absolute day", int.MaxValue, 1, int.MaxValue, null, long.MaxValue, 2L, 5, 1, 2, 2, 8589934590L, 2147483647L, 4611686014132420609L, "2147483647/2147483647/4611686014132420609/uniform:2147483647")
    };

    private static readonly AgeVector[] AgeVectors =
    {
        new AgeVector("conventional day before birthday", 12, 1, 30, null, 64L, 423L, 0L),
        new AgeVector("conventional birthday", 12, 1, 30, null, 64L, 424L, 1L),
        new AgeVector("conventional day after birthday", 12, 1, 30, null, 64L, 425L, 1L),
        new AgeVector("unequal day before birthday", 3, 1, 1, new[] { 10, 20, 5 }, 9L, 43L, 0L),
        new AgeVector("unequal birthday", 3, 1, 1, new[] { 10, 20, 5 }, 9L, 44L, 1L),
        new AgeVector("unequal day after birthday", 3, 1, 1, new[] { 10, 20, 5 }, 9L, 45L, 1L)
    };

    [Test]
    public void ExactDateVectorsMatchExpectedFieldsAndSemanticIdentity()
    {
        foreach (DateVector vector in DateVectors)
        {
            SimulationCalendar calendar = CreateCalendar(vector.MonthsPerYear, vector.WeeksPerMonth, vector.DaysPerWeek, vector.CustomMonthLengths);
            SimulationDate actual = calendar.GetDate(vector.AbsoluteDay);

            Assert.That(actual.AbsoluteDay, Is.EqualTo(vector.AbsoluteDay), vector.Name);
            Assert.That(actual.Year, Is.EqualTo(vector.Year), vector.Name);
            Assert.That(actual.Month, Is.EqualTo(vector.Month), vector.Name);
            Assert.That(actual.WeekOfMonth, Is.EqualTo(vector.WeekOfMonth), vector.Name);
            Assert.That(actual.DayOfMonth, Is.EqualTo(vector.DayOfMonth), vector.Name);
            Assert.That(actual.DayOfWeek, Is.EqualTo(vector.DayOfWeek), vector.Name);
            Assert.That(actual.DayOfYear, Is.EqualTo(vector.DayOfYear), vector.Name);
            Assert.That(actual.DaysPerMonth, Is.EqualTo(vector.DaysPerMonth), vector.Name);
            Assert.That(actual.DaysPerYear, Is.EqualTo(vector.DaysPerYear), vector.Name);
            Assert.That(calendar.SemanticIdentity, Is.EqualTo("simulation-calendar"), vector.Name);
            Assert.That(calendar.SemanticVersion, Is.EqualTo(vector.SemanticVersion), vector.Name);
            Assert.That(calendar.GetAbsoluteDay(actual), Is.EqualTo(vector.AbsoluteDay), vector.Name);
        }
    }

    [Test]
    public void BirthdayVectorsMatchBeforeOnAndAfterBoundaries()
    {
        foreach (AgeVector vector in AgeVectors)
        {
            SimulationCalendar calendar = CreateCalendar(vector.MonthsPerYear, vector.WeeksPerMonth, vector.DaysPerWeek, vector.CustomMonthLengths);
            long actual = calendar.CalculateAge(calendar.GetDate(vector.BirthAbsoluteDay), calendar.GetDate(vector.CurrentAbsoluteDay));

            Assert.That(actual, Is.EqualTo(vector.ExpectedAge), vector.Name);
        }
    }

    [Test]
    public void NegativeAbsoluteDayIsRejected()
    {
        SimulationCalendar calendar = new SimulationCalendar(new CalendarDefinition(12, 1, 30));

        Assert.Throws<ArgumentOutOfRangeException>(() => calendar.GetDate(-1L));
    }

    [Test]
    public void InverseOverflowIsRejected()
    {
        SimulationCalendar calendar = new SimulationCalendar(new CalendarDefinition(12, 1, 30));
        SimulationDate date = new SimulationDate(0L, long.MaxValue, 1, 1, 1, 1, 1L, 30L, 360L);

        Assert.Throws<ArgumentOutOfRangeException>(() => calendar.GetAbsoluteDay(date));
    }

    [Test]
    public void InvalidCalendarConfigurationIsRejected()
    {
        CalendarDefinition definition = new CalendarDefinition(1, 1, 1);
        definition.monthsPerYear = 0;

        Assert.Throws<ArgumentException>(() => new SimulationCalendar(definition));
    }

    private static SimulationCalendar CreateCalendar(int monthsPerYear, int weeksPerMonth, int daysPerWeek, int[] customMonthLengths)
    {
        CalendarDefinition definition = customMonthLengths == null
            ? new CalendarDefinition(monthsPerYear, weeksPerMonth, daysPerWeek)
            : new CalendarDefinition(customMonthLengths, daysPerWeek);
        return new SimulationCalendar(definition);
    }

    private sealed class DateVector
    {
        public readonly string Name;
        public readonly int MonthsPerYear;
        public readonly int WeeksPerMonth;
        public readonly int DaysPerWeek;
        public readonly int[] CustomMonthLengths;
        public readonly long AbsoluteDay;
        public readonly long Year;
        public readonly int Month;
        public readonly int WeekOfMonth;
        public readonly int DayOfMonth;
        public readonly int DayOfWeek;
        public readonly long DayOfYear;
        public readonly long DaysPerMonth;
        public readonly long DaysPerYear;
        public readonly string SemanticVersion;

        public DateVector(string name, int monthsPerYear, int weeksPerMonth, int daysPerWeek, int[] customMonthLengths, long absoluteDay,
            long year, int month, int weekOfMonth, int dayOfMonth, int dayOfWeek, long dayOfYear, long daysPerMonth, long daysPerYear, string semanticVersion)
        {
            Name = name;
            MonthsPerYear = monthsPerYear;
            WeeksPerMonth = weeksPerMonth;
            DaysPerWeek = daysPerWeek;
            CustomMonthLengths = customMonthLengths;
            AbsoluteDay = absoluteDay;
            Year = year;
            Month = month;
            WeekOfMonth = weekOfMonth;
            DayOfMonth = dayOfMonth;
            DayOfWeek = dayOfWeek;
            DayOfYear = dayOfYear;
            DaysPerMonth = daysPerMonth;
            DaysPerYear = daysPerYear;
            SemanticVersion = semanticVersion;
        }
    }

    private sealed class AgeVector
    {
        public readonly string Name;
        public readonly int MonthsPerYear;
        public readonly int WeeksPerMonth;
        public readonly int DaysPerWeek;
        public readonly int[] CustomMonthLengths;
        public readonly long BirthAbsoluteDay;
        public readonly long CurrentAbsoluteDay;
        public readonly long ExpectedAge;

        public AgeVector(string name, int monthsPerYear, int weeksPerMonth, int daysPerWeek, int[] customMonthLengths,
            long birthAbsoluteDay, long currentAbsoluteDay, long expectedAge)
        {
            Name = name;
            MonthsPerYear = monthsPerYear;
            WeeksPerMonth = weeksPerMonth;
            DaysPerWeek = daysPerWeek;
            CustomMonthLengths = customMonthLengths;
            BirthAbsoluteDay = birthAbsoluteDay;
            CurrentAbsoluteDay = currentAbsoluteDay;
            ExpectedAge = expectedAge;
        }
    }
}
